var datum, txt, BerechnungA;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile
// -------->>>> LADUNG
schedule("* * * * * *", async () => {
  if ((getState('go-e.0.unlocked_by').val == 0) && (getState('go-e.0.car').val > 1)) {
    // Timer - nach Stop
    setState('0_userdata.0.go-e.Timeout' /* Timeout */, (Math.min(Math.max(getState('0_userdata.0.go-e.Timeout').val, 0), 999)), true);
    if (getState('0_userdata.0.go-e.Timeout').val > 0) {
      setState('0_userdata.0.go-e.Timeout' /* Timeout */, (Math.min(Math.max(getState('0_userdata.0.go-e.Timeout').val - 1, 0), 999)), true);
    }
    // --------->>>>> LADUNG STOP / ZIEL
    if (getState('0_userdata.0.go-e.LADUNG').val == true && getState('go-e.0.allow_charging').val == true && getState('alias.0.EM24 Hall Grid.Power').val >= 4000) {
      setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, false);
      setState('go-e.0.access_state' /* Access State (ast) */, 1);
      setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Ladung gestoppt - zu viel Bezug ---------------------------------');
    } else if (getState('0_userdata.0.go-e.AUTO').val == false && getState('0_userdata.0.go-e.NOT').val == false && (getState('0_userdata.0.go-e.LADUNG').val == true || getState('go-e.0.car').val <= 1)) {
      setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, false);
      setState('go-e.0.access_state' /* Access State (ast) */, 1);
      setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Ladung gestoppt ---------------------------------');
      setState('0_userdata.0.go-e.Timeout' /* Timeout */, 120, true);
    } else if (false) {
      setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, false);
      setState('go-e.0.access_state' /* Access State (ast) */, 1);
      setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Ladung gestoppt - Zielladung erreicht -------------------------------');
    } else if (getState('go-e.0.car').val <= 1 && getState('0_userdata.0.go-e.LADUNG').val == true) {
      setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, false);
      setState('go-e.0.access_state' /* Access State (ast) */, 1);
      setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 0);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Ladung gestoppt - kein Auto angehängt -------------------------------');
    }
    // ---------Entscheidung----------
    if (getState('0_userdata.0.go-e-phases.go_E_Zuleitung_Emergency_STOP').val) {
      console.debug('go-e Grid Emergency Stop');
      if (getState('go-e.0.allow_charging').val) {
        setState('go-e.0.access_state' /* Access State (ast) */, 1);
        setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 0);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Emergency STOP !!!');
        setState('0_userdata.0.go-e.Timeout' /* Timeout */, 120, true);
      }
    } else if (false) {
    } else if (getState('0_userdata.0.go-e.Timeout').val == 0) {
      // -------->>>> MIN Ladung starten
      // -------->>>> NOT Ladung starten
      if (getState('0_userdata.0.go-e.NOT').val == true && getState('go-e.0.car').val > 1 && getState('0_userdata.0.go-e.LADUNG').val == false) {
        setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, true);
        setState('go-e.0.access_state' /* Access State (ast) */, 0);
        setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 1);
        setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e.minA').val));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / NOT Ladung gestartet ---------------------------------');
        setState('0_userdata.0.go-e.Timeout' /* Timeout */, 20, true);
      }
      // --------->>>>> AUTO LADUNG starten
      if (getState('0_userdata.0.go-e.AUTO').val == true && getState('go-e.0.car').val > 1 && getState('0_userdata.0.go-e.LADUNG').val == false) {
        setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, true);
        setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e.minA').val));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / AUTO Ladung aktiviert ---------------------------------');
      } else if (false) {
      }
    }
    // --->> Ladung steuern
    if (getState('0_userdata.0.go-e.Timeout').val == 0 && getState('0_userdata.0.go-e.AUTO').val == 1 && (getState('0_userdata.0.go-e.LADUNG').val == true || getState('0_userdata.0.go-e.MinLadungAktiv').val == true)) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / ----------- Steuer - Zyklus beginnt -----------');
      // kein Überschuss vorhanden - stoppe Ladung
      if ((getState('alias.0.EM24 Hall Grid.Power').val >= getState('0_userdata.0.go-e.maxBezug').val || getState('alias.0.Fronius.AC-Power').val < 1100) && getState('go-e.0.allow_charging').val == 1 && !getState('0_userdata.0.go-e.MinLadungAktiv').val) {
        setState('go-e.0.access_state' /* Access State (ast) */, 1);
        setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 0);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / AUTO Ladung gestoppt');
        setState('0_userdata.0.go-e.Timeout' /* Timeout */, 120, true);
      } else {
        // Überschuss vorhanden - starte AUTO Ladung
        if ((getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > getState('0_userdata.0.go-e.minPV').val || getState('0_userdata.0.go-e.MinLadungAktiv').val) && getState('go-e.0.allow_charging').val == 0) {
          setState('go-e.0.access_state' /* Access State (ast) */, 0);
          setState('go-e.0.allow_charging' /* Allow Charging (alw) */, 1);
          setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e.minA').val));
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / AUTO Ladung gestartet');
        }
      }
      // weniger Überschuss vorhanden, Strom reduzieren
      if ((getState('alias.0.EM24 Hall Grid.PV_Überschuss').val <= getState('0_userdata.0.go-e.minPV').val || getState('alias.0.EM24 Hall Grid.PV_Überschuss').val == 0 && getState('0_userdata.0.go-e.minPV').val == 0) && getState('go-e.0.allow_charging').val == 1) {
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / Leistung go-E (kW): ' + String(getState('go-e.0.energy.power').val));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / Überschussleistung (W): ' + String(getState('alias.0.EM24 Hall Grid.PV_Überschuss').val));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / min.PVÜberschuss (W): ' + String(getState('0_userdata.0.go-e.minPV').val));
        if (getState('alias.0.EM24 Hall Grid.Power').val < 0) {
          BerechnungA = Math.min(Math.max((getState('alias.0.EM24 Hall Grid.PV_Überschuss').val + getState('go-e.0.energy.power').val * 1000) - getState('0_userdata.0.go-e.minPV').val, 0), 11040);
        } else {
          BerechnungA = Math.min(Math.max((getState('go-e.0.energy.power').val * 1000 - getState('alias.0.EM24 Hall Grid.Power').val) - getState('0_userdata.0.go-e.minPV').val, 0), 11040);
        }
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / Überschussleistung (W): ' + String(BerechnungA));
        if (getState('0_userdata.0.go-e.3P').val == true) {
          BerechnungA = BerechnungA / 3;
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / Überschussleistung pro Phase (W): ' + String(BerechnungA));
        }
        BerechnungA = BerechnungA / 230;
        BerechnungA = Math.round(BerechnungA - 0.5);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / berechneter Strom Min/Max (A): ' + String(BerechnungA));
        BerechnungA = Math.min(Math.max(BerechnungA, getState('0_userdata.0.go-e.minA').val), getState('0_userdata.0.go-e.maxA').val);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / begrenzter Strom (A): ' + String(BerechnungA));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / akt. Ladestrom (A): ' + String(getState('go-e.0.ampere').val));
        if (BerechnungA < getState('go-e.0.ampere').val) {
          setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, (Math.min(Math.max(BerechnungA, getState('0_userdata.0.go-e.minA').val), getState('0_userdata.0.go-e.maxA').val)));
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / Reduzierung / neuer Ladestrom (A): ' + String(BerechnungA));
          await wait(1000);
        }
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / ----------- Steuer - Zyklus endet -----------');
    } else if (getState('0_userdata.0.go-e.NOT').val == true && getState('go-e.0.allow_charging').val == true) {
      if (getState('0_userdata.0.go-e.minA').val != getState('go-e.0.amperePV').val) {
        setState('go-e.0.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, getState('0_userdata.0.go-e.minA').val);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'go-e / minA geändert / neuer Ladestrom (A): ' + String(BerechnungA));
      }
    }
  }
});


